#!/usr/bin/env bash
# Composed-dataplane E2E: two chronicle .fmods wired in ONE graph — pipeline
# (IR-at-load, doubles amount) feeding aggregation (windowed sums). The same
# five events as aggregation-e2e, but every sum arrives doubled:
#   alice [0,100)  count=2 sum=600    bob [0,100) count=1 sum=100
#   alice [100,200) count=1 sum=1998
. "$(dirname "$0")/../lib.sh"
modules_ready || { no composed "fluxor modules build failed"; finish; exit; }

build_graph examples/composed/linux.yaml || { no composed build; finish; exit; }




got=$(run_hex $IN 6)
[ "$got" = "$WANT" ] && ok "composed pipeline->aggregation doubles every pane sum" \
  || no composed "got=$got"

finish
